/// <summary>
/// Example UPSPricingAttribute of table <c>RetailInventTable</c> field scaleItem.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeRetailInventTableScaleItem extends UPSPricingAttributeRetailInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, scaleItem);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    RetailInventTable retailInventTable;
    while select scaleItem from retailInventTable
        group by scaleItem
    {
        ret.add(retailInventTable.scaleItem);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailInventTable, scaleItem));
    qbr.value(queryValue(_value));
}
